-- ACME Retail - Supabase Storage buckets/policies (T50, T214, T295) and Realtime publication.

-- Product images: public read by URL (catalog), size and MIME limited, no listing, writes by catalog/admin only.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('product-images', 'product-images', true, 2097152, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update
  set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

-- object keys are generated by the server: products/<product uuid>/<random uuid>.<ext>
create policy "product images: catalog insert" on storage.objects for insert to authenticated
  with check (bucket_id = 'product-images' and app.has_permission('catalog:write')
              and name ~ '^products/[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|png|webp)$');
create policy "product images: catalog delete" on storage.objects for delete to authenticated
  using (bucket_id = 'product-images' and app.has_permission('catalog:write'));
-- no SELECT policy: the bucket cannot be listed through the API; files are served by public URL only.

-- Realtime: clients receive changes only for rows RLS lets them read.
alter publication supabase_realtime add table public.orders, public.events, public.inventory;
